    if($guestCustomerId){$delete=$db->prepare('DELETE FROM restaurant_customers WHERE id=? AND restaurant_id=? AND NOT EXISTS(SELECT 1 FROM orders WHERE customer_id=?)');$delete->execute([$guestCustomerId,(int)$fixture['id'],$guestCustomerId]);}
    $restore=$db->prepare('UPDATE restaurants SET online_ordering_enabled=? WHERE id=?');$restore->execute([(int)$fixture['online_ordering_enabled'],(int)$fixture['id']]);
    $restoreMinimum=$db->prepare('UPDATE restaurants SET delivery_minimum=? WHERE id=?');$restoreMinimum->execute([(string)$fixture['delivery_minimum'],(int)$fixture['id']]);
    if($cookieFile&&is_file($cookieFile))unlink($cookieFile);
    echo "Temporary online orders and customer test record cleaned up.\n";
}
